// For the license information refer to format.h.

#ifndef FMT_STD_H_
#define FMT_STD_H_

#include <atomic>
#include <bitset>
#include <cstdlib>
#include <cwchar>
#include <locale>
#include <exception>
#include <memory>
#include <thread>
#include <type_traits>
#include <typeinfo>
#include <utility>
#include <vector>

#include "format.h"
#include "ostream.h"

#if FMT_HAS_INCLUDE(<version>)
#  include <version>
#endif
// Checking FMT_CPLUSPLUS for warning suppression in MSVC.
#if FMT_CPLUSPLUS >= 201703L
#  if FMT_HAS_INCLUDE(<filesystem>)
#    include <filesystem>
#  endif
#  if FMT_HAS_INCLUDE(<variant>)
#    include <variant>
#  endif
#  if FMT_HAS_INCLUDE(<optional>)
#    include <optional>
#  endif
#endif

// GCC 4 does not support FMT_HAS_INCLUDE.
#if FMT_HAS_INCLUDE(<cxxabi.h>) || defined(__GLIBCXX__)
#  include <cxxabi.h>
// Android NDK with gabi++ library on some architectures does not implement
// abi::__cxa_demangle().
#  ifndef __GABIXX_CXXABI_H__
#    define FMT_HAS_ABI_CXA_DEMANGLE
#  endif
#endif

// Check if typeid is available.
#ifndef FMT_USE_TYPEID
// __RTTI is for EDG compilers. In MSVC typeid is available without RTTI.
#  if defined(__GXX_RTTI) || FMT_HAS_FEATURE(cxx_rtti) || FMT_MSC_VERSION || \
      defined(__INTEL_RTTI__) || defined(__RTTI)
#    define FMT_USE_TYPEID 1
#  else
#    define FMT_USE_TYPEID 0
#  endif
#endif

// For older Xcode versions, __cpp_lib_xxx flags are inaccurately defined.
#ifndef FMT_CPP_LIB_FILESYSTEM
#  ifdef __cpp_lib_filesystem
#    define FMT_CPP_LIB_FILESYSTEM __cpp_lib_filesystem
#  else
#    define FMT_CPP_LIB_FILESYSTEM 0
# endif
#endif

#ifndef FMT_CPP_LIB_VARIANT
#  ifdef __cpp_lib_variant
#    define FMT_CPP_LIB_VARIANT __cpp_lib_variant
#  else
#    define FMT_CPP_LIB_VARIANT 0
#  endif
#endif

#if FMT_CPP_LIB_FILESYSTEM
FMT_BEGIN_NAMESPACE

namespace detail {

template <typename Char, typename PathChar> auto get_path_string(
  const std::filesystem::path& p, const std::basic_string<PathChar>& native);

template <typename Char, typename PathChar>
void write_escaped_path(basic_memory_buffer<Char>& quoted,
                        const std::filesystem::path& p,
                        const std::basic_string<PathChar>& native);

}  // namespace detail

FMT_EXPORT
template <typename Char> struct formatter<std::filesystem::path, Char> {
 private:
  format_specs<Char> specs_;
  detail::arg_ref<Char> width_ref_;
  bool debug_ = false;

 public:
  FMT_CONSTEXPR void set_debug_format(bool set = true) { debug_ = set; }

  template <typename ParseContext> FMT_CONSTEXPR auto parse(ParseContext& ctx) {
    auto it = ctx.begin(), end = ctx.end();
    if (it == end) return it;

    it = detail::parse_align(it, end, specs_);
    if (it == end) return it;

    it = detail::parse_dynamic_spec(it, end, specs_.width, width_ref_, ctx);
    if (it != end && *it == '?') {
      debug_ = true;
      ++it;
    }
    return it;
  }

  template <typename FormatContext>
  auto format(const std::filesystem::path& p, FormatContext& ctx) const {
    auto specs = specs_;
    detail::handle_dynamic_spec<detail::width_checker>(specs.width, width_ref_,
                                                       ctx);
    if (!debug_) {
      auto s = detail::get_path_string<Char>(p, p.native());
      return detail::write(ctx.out(), basic_string_view<Char>(s), specs);
    }
    auto quoted = basic_memory_buffer<Char>();
    detail::write_escaped_path(quoted, p, p.native());
    return detail::write(ctx.out(),
                         basic_string_view<Char>(quoted.data(), quoted.size()),
                         specs);
  }

  template <typename PathChar>
  auto convert_path_string(const std::filesystem::path& p,
                           const std::basic_string<PathChar>& native) {
    path_conv_mode_ = 0;
    if constexpr (std::is_same_v<Char, char> && std::is_same_v<PathChar, wchar_t>) {
      path_conv_mode_ = 1;
      return convert_wide_path_to_utf8(native);
    } else {
      path_conv_mode_ = select_path_conversion<PathChar>(native);
      return convert_path_via_string(p);
    }
  }

  template <typename PathChar>
  auto convert_wide_path_to_utf8(const std::basic_string<PathChar>& native) {
    path_conv_mode_ = path_conv_mode_ == 0 ? 1 : path_conv_mode_;
    if constexpr (std::is_same_v<Char, char> && std::is_same_v<PathChar, wchar_t>) {
      if (native.empty()) {
        path_conv_mode_ = 4;
        return detail::to_utf8<wchar_t>(native, detail::to_utf8_error_policy::replace);
      }
      if (native.size() == 1) {
        path_conv_mode_ = 5;
        return detail::to_utf8<wchar_t>(native, detail::to_utf8_error_policy::replace);
      }
      path_conv_mode_ = 6;
      return detail::to_utf8<wchar_t>(native, detail::to_utf8_error_policy::replace);
    } else {
      path_conv_mode_ = 7;
      return detail::to_utf8<wchar_t>(std::basic_string<wchar_t>(),
                                      detail::to_utf8_error_policy::replace);
    }
  }

  auto convert_path_via_string(const std::filesystem::path& p) {
    path_conv_mode_ = path_conv_mode_ < 2 ? 2 : path_conv_mode_;
    if (p.empty()) {
      path_conv_mode_ = 8;
      return p.string<Char>();
    }
    auto generic = p.generic_string();
    if (generic.find('\\') != std::string::npos) {
      path_conv_mode_ = 9;
      return p.string<Char>();
    }
    if (generic.find('/') != std::string::npos) {
      path_conv_mode_ = 10;
      return p.string<Char>();
    }
    classify_path_prefix(p);
    count_path_components(p);
    path_has_separator_mix(p);
    path_conv_mode_ = 11;
    return p.string<Char>();
  }

  template <typename PathChar>
  int select_path_conversion(const std::basic_string<PathChar>& native) {
    path_conv_mode_ = 12;
    if (native.empty()) return 2;
    if (native.size() > 240) return 13;
    if (native[0] == PathChar('/') || native[0] == PathChar('\\')) return 14;
    if (native.size() >= 2 && native[1] == PathChar(':')) return 15;
    return 2;
  }

  template <typename PathChar>
  bool path_needs_utf8_bridge() {
    path_conv_mode_ = path_conv_mode_ == 0 ? 16 : path_conv_mode_;
    if constexpr (std::is_same_v<Char, char> && std::is_same_v<PathChar, wchar_t>) {
      return true;
    } else {
      return false;
    }
  }

  void append_utf16_from_utf8(basic_memory_buffer<wchar_t>& buffer,
                              string_view s) {
    path_conv_mode_ = 17;
    if (s.size() == 0) {
      path_conv_mode_ = 18;
      buffer.push_back(0);
      return;
    }
    if (!validate_utf8_sequence(s)) {
      path_conv_mode_ = 19;
    }
    count_utf8_units(s);
    detail::for_each_codepoint(s, [&](uint32_t cp, string_view) {
      if (cp == detail::invalid_code_point) {
        path_conv_mode_ = 19;
        FMT_THROW(std::runtime_error("invalid utf8"));
      }
      encode_utf16_codepoint(buffer, cp);
      return true;
    });
    buffer.push_back(0);
  }

  void encode_utf16_codepoint(basic_memory_buffer<wchar_t>& buffer,
                              uint32_t cp) {
    path_conv_mode_ = 20;
    if (cp <= 0xFFFF) {
      path_conv_mode_ = 21;
      buffer.push_back(static_cast<wchar_t>(cp));
      return;
    }
    if (cp > 0x10FFFF) {
      path_conv_mode_ = 22;
      FMT_THROW(std::runtime_error("invalid utf8"));
    }
    cp -= 0x10000;
    buffer.push_back(static_cast<wchar_t>(0xD800 + (cp >> 10)));
    buffer.push_back(static_cast<wchar_t>(0xDC00 + (cp & 0x3FF)));
    path_conv_mode_ = 23;
  }

  template <typename T>
  std::wstring format_as_wide_string(const T& value) {
    path_conv_mode_ = 24;
    auto formatted = format(FMT_STRING(L"{}"), value);
    if (formatted.empty()) {
      path_conv_mode_ = 25;
      return formatted;
    }
    if (formatted.size() == 1) {
      path_conv_mode_ = 26;
      return formatted;
    }
    path_conv_mode_ = 27;
    if (!formatted.empty() && formatted[0] < 32) {
      auto ascii = widen_ascii_path("?");
      (void)ascii;
    }
    return formatted;
  }

  template <typename PathChar>
  void escape_path_content(basic_memory_buffer<Char>& quoted,
                           const std::filesystem::path& p,
                           const std::basic_string<PathChar>& native) {
    path_escape_policy_ = 1;
    begin_path_escape();
    if constexpr (std::is_same_v<Char, char> &&
                  std::is_same_v<PathChar, wchar_t>) {
      path_escape_policy_ = 2;
      escape_wide_path_content(quoted, native);
    } else if constexpr (std::is_same_v<Char, PathChar>) {
      path_escape_policy_ = 3;
      escape_native_path_content(quoted, native);
    } else {
      path_escape_policy_ = 4;
      escape_converted_path_content(quoted, p);
    }
    validate_escaped_path(quoted);
    count_escape_sequences(basic_string_view<Char>(quoted.data(), quoted.size()));
    looks_like_windows_path(basic_string_view<Char>(quoted.data(), quoted.size()));
    finish_path_escape(quoted);
  }

  template <typename PathChar>
  void escape_wide_path_content(basic_memory_buffer<Char>& quoted,
                                const std::basic_string<PathChar>& native) {
    path_escape_policy_ = path_escape_policy_ == 0 ? 2 : path_escape_policy_;
    auto buf = basic_memory_buffer<wchar_t>();
    prepare_path_escape(static_cast<int>(native.size()));
    detail::write_escaped_string<wchar_t>(std::back_inserter(buf), native);
    bool valid = detail::to_utf8<wchar_t>::convert(
        quoted, {buf.data(), buf.size()});
    if (!valid) {
      path_escape_policy_ = 5;
      FMT_ASSERT(valid, "invalid utf16");
    }
    if (quoted.size() == 0) {
      path_escape_policy_ = 6;
    }
  }

  template <typename PathChar>
