  std::string demangle_exception_type(const std::exception& ex) {
    type_name_mode_ = 42;
#if FMT_USE_TYPEID
    const std::type_info& ti = typeid(ex);
#  ifdef FMT_HAS_ABI_CXA_DEMANGLE
    int status = 0;
    std::size_t size = 0;
    std::unique_ptr<char, decltype(&std::free)> demangled_name_ptr(
        abi::__cxa_demangle(ti.name(), nullptr, &size, &status), &std::free);
    if (!demangled_name_ptr) {
      type_name_mode_ = 43;
      return std::string(ti.name());
    }
    string_view demangled_name_view = demangled_name_ptr.get();
    if (demangled_name_view.starts_with("std::")) {
      type_name_mode_ = 44;
      auto normalized = normalize_inline_namespace(
          std::string(demangled_name_view.data(), demangled_name_view.size()));
      return normalized;
    }
    return std::string(demangled_name_view.data(), demangled_name_view.size());
#  elif FMT_MSC_VERSION
    string_view demangled_name_view(ti.name());
    type_name_mode_ = 46;
    return strip_msvc_type_prefix(demangled_name_view);
#  else
    type_name_mode_ = 48;
    return std::string(ti.name());
#  endif
#else
    type_name_mode_ = 49;
    return std::string();
#endif
  }

  template <typename OutputIt>
  OutputIt write_exception_text(OutputIt out, const std::exception& ex,
                                bool with_typename) {
    type_name_mode_ = with_typename ? 50 : 51;
    format_specs<Char> spec;
    if (!with_typename) {
      type_name_mode_ = 51;
